'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token = $('meta[name="researchos-token"]').content;
const kinds = ['projects','datasets','hypotheses','experiments','runs','papers','notes','decisions'];
const names = {projects:'Project', datasets:'Data version', hypotheses:'Hypotheses', experiments:'Experiment', runs:'Runs', papers:'Paper evidence', notes:'Research notes', decisions:'Next steps'};
const labels = {active:'Active',paused:'Paused',archived:'Archived',proposed:'Proposed',testing:'Testing',supported:'Supported',inconclusive:'Inconclusive',refuted:'Refuted',planned:'Planned',running:'Running',completed:'Completed',failed:'Failed',todo:'To do',doing:'Active',done:'Completed',dismissed:'Dismissed',high:'High priority',medium:'Medium priority',low:'Low priority',context:'Background',supports:'Supporting evidence',contradicts:'Contradicting evidence',method:'Method'};
const paths = {refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 2 M18 18a8 8 0 0 1-13-2',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V5a1 1 0 0 1 1-1h6l2 3h8a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z',bulb:'M9 18h6 M10 21h4 M8 15a7 7 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3',flask:'M9 3h6 M10 3v7L4 19q-1 2 2 2h12q3 0 2-2l-6-9V3 M7 16h10',book:'M3 4h7q2 0 2 2v15q0-2-2-2H3z M21 4h-7q-2 0-2 2v15q0-2 2-2h7z',note:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',arrow:'M4 12h16 M14 6l6 6-6 6',check:'M5 12l4 4L19 6',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',plus:'M12 5v14 M5 12h14',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',close:'M6 6l12 12 M18 6L6 18',chevron:'M9 5l7 7-7 7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',git:'M6 3v12a4 4 0 0 0 4 4h8 M6 5a2 2 0 1 0 0 .01 M18 17a2 2 0 1 0 0 .01 M17 5v4a4 4 0 0 1-4 4H6',link:'M9 15l6-6 M8 16l-2 2a4 4 0 0 1-6-6l5-5 M16 8l2-2a4 4 0 0 1 6 6l-5 5',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',copy:'M8 8h13v13H8z M16 8V3H3v13h5',chart:'M4 3v17h17 M7 15l4-5 4 2 5-7',menu:'M4 6h16 M4 12h16 M4 18h16',dot:'M12 12h.01',database:'M3 6c0-5 18-5 18 0s-18 5-18 0v12c0 5 18 5 18 0V6 M3 12c0 5 18 5 18 0',external:'M14 3h7v7 M21 3L10 14 M10 3H3v18h18v-7'};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.note}"/></svg>`;
const S = {data:null, page:'overview', project:localStorage.getItem('ros-project')||'', filter:'', query:'', selected:new Set(), compare:null, detail:null};
let lastFocus, formDirty=false, currentForm=null, csvPreview=null;
const format = (n, digits=3) => n == null ? '—' : Number(n).toFixed(digits);
const date = (d, opts={month:'short',day:'numeric'}) => d ? new Date(d).toLocaleDateString('en-US',opts) : 'Not set';
const status = value => `<span class="status ${esc(value)}"><i></i>${esc(labels[value]||value)}</span>`;
const find = (kind,id) => S.data?.[kind]?.find(x=>x.id===id);
const list = kind => (S.data?.[kind]||[]).filter(x=>!S.project || (kind==='projects'?x.id:x.project_id)===S.project);
const project = id => find('projects', id);
const pmark = id => {const p=project(id);return p?`<span class="project-label"><i style="--project:${esc(p.color)}"></i>${esc(p.name)}</span>`:'';};
const btn = (label, action, attrs='', cls='') => `<button class="button ${cls}" data-action="${action}" ${attrs} ${!label.replace(/<[^>]*>/g,'').trim()&&!attrs.includes('aria-label')?`aria-label="${({new:'New record',detail:'View details',mobile:'Open navigation'})[action]||'Action'}"`: ''}>${label}</button>`;
const openLink = (kind,item,cls='text-link') => `<button class="${cls}" data-action="detail" data-kind="${kind}" data-id="${esc(item.id)}">${esc(item.title||item.name)}</button>`;
const titleOf = item => item?.name || item?.title || `Seed ${item?.seed}`;
const metricStats = exp => { const runs=S.data.runs.filter(r=>r.experiment_id===exp.id && r.status==='completed'); const vals=runs.map(r=>r.metrics[exp.metric]).filter(Number.isFinite);const mean=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;const sd=vals.length>1?Math.sqrt(vals.reduce((a,v)=>a+(v-mean)**2,0)/(vals.length-1)):null;return {n:vals.length,mean,sd,runs}; };
async function api(path, data, method='POST') {
  const response = await fetch('/api/'+path,{method:data===undefined?'GET':method,headers:{'X-ResearchOS-Token':token,...(data!==undefined?{'Content-Type':'application/json'}:{})},body:data===undefined?undefined:JSON.stringify(data)});
  let result; try {result=await response.json();} catch {throw new Error('Invalid response from the local service. Restart Research OS.');}
  if(!response.ok) throw new Error(result.error||'Action failed');return result;
}
async function refresh(render=true) {S.data=await api('state');S.compare=null;S.selected=new Set([...S.selected].filter(id=>find('experiments',id)));if(S.project&&!project(S.project))S.project='';if(render)draw();}
function toast(message,error=false) {const el=$('#toast');el.textContent=message;el.className=error?'show error':'show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',error?6500:3500);}
function empty(title,description,action='new',kind=S.page) {return `<div class="empty"><div class="empty-icon">${icon(kind==='experiments'?'flask':'plus')}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${btn('New '+(names[kind]||'Project'),action,`data-kind="${kind}"`,'primary')}</div>`;}
const navs=[['overview','grid','Overview'],['projects','folder','Research projects'],['hypotheses','bulb','Hypotheses'],['experiments','flask','Experiment tracking'],['papers','book','Paper evidence'],['notes','note','Research notes'],['decisions','arrow','Next steps']];
function draw(){
 const active=S.data.projects.filter(p=>p.status==='active');
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">r<span>•</span></span><span>Research OS<small>MAKE RESEARCH CONNECT.</small></span></a><button class="workspace" data-action="nav" data-page="projects"><span class="workspace-avatar">N</span><span>Personal research space<small>Local workspace</small></span>${icon('chevron')}</button><div class="nav-caption">WORKSPACE</div><nav>${navs.map(([page,ic,label])=>`<button class="nav-item ${S.page===page?'active':''}" data-action="nav" data-page="${page}">${icon(ic)}<span>${label}</span>${page==='decisions'?`<b>${list('decisions').filter(d=>['todo','doing'].includes(d.status)).length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-projects"><div class="nav-caption">YOUR PROJECTS ${btn(icon('plus'),'new','data-kind="projects"','icon-only')}</div>${active.slice(0,5).map(p=>`<button class="project-nav ${S.project===p.id?'selected':''}" data-action="scope" data-id="${p.id}"><i style="background:${esc(p.color)}"></i><span>${esc(p.name)}</span></button>`).join('')||'<p class="muted small">No active projects</p>'}</div><div class="sidebar-bottom"><div class="local-status"><span></span>Data stays on this Mac <small>LOCAL · PRIVATE</small></div><button class="nav-item ${S.page==='settings'?'active':''}" data-action="nav" data-page="settings">${icon('settings')}<span>Settings and data</span><span class="version">v1.0</span></button></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">${btn(icon('menu'),'mobile','','icon-only mobile-toggle')}<span>Workspace</span>${icon('chevron')}<strong>${navs.find(n=>n[0]===S.page)?.[2]||'Settings and data'}</strong></div><div class="top-actions">${btn(icon('refresh'),'refresh','aria-label="Refresh workspace" title="Refresh workspace"','icon-only')}<button class="search-trigger" data-action="search">${icon('search')}<span>Search workspace</span><kbd>⌘ K</kbd></button><span class="avatar">N</span></div></header><main id="main" tabindex="-1">${S.data.datasets.some(d=>d.version==='demo-v1')?'<div class="notice warning">Demo data: experiments, metrics and Git versions marked demo-v1 are synthetic examples, not real research results.</div>':''}${renderPage()}</main><footer class="main-footer"><span>Research OS</span><span>Every conclusion has a source.</span><span class="saved">${icon('check')} Loaded from the local database</span></footer></div>`;
 document.title=`${navs.find(n=>n[0]===S.page)?.[2]||'Settings'} · Research OS`;
}
function heading(eyebrow,title,desc,actions=''){return `<section class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></section>`;}
function scopeControl(){return `<label class="scope-select">${icon('folder')}<select id="project-scope" aria-label="Filter projects"><option value="">All projects</option>${S.data.projects.map(p=>`<option value="${p.id}" ${S.project===p.id?'selected':''}>${esc(p.name)}${p.status==='archived'?' (Archive)':''}</option>`).join('')}</select></label>`;}
function toolbar(kind,extra=''){return `<div class="toolbar"><div class="toolbar-left">${scopeControl()}<div class="list-search">${icon('search')}<input id="list-query" aria-label="Search this list" placeholder="Search this list…" value="${esc(S.query)}"></div></div>${extra}</div>`;}
function filtered(kind){let items=list(kind);if(S.query)items=items.filter(x=>JSON.stringify(x).toLowerCase().includes(S.query.toLowerCase()));if(S.filter)items=items.filter(x=>x.status===S.filter);return items;}
function tabs(values){return `<div class="filter-tabs">${[['','All'],...values.map(v=>[v,labels[v]])].map(([key,value])=>`<button data-action="filter" data-value="${key}" class="${S.filter===key?'active':''}">${value}</button>`).join('')}</div>`;}
function renderPage(){
 if(S.page==='overview')return overview();
 if(S.page==='projects')return projectsPage();
 if(S.page==='experiments')return experimentsPage();
 if(S.page==='hypotheses')return hypothesesPage();
 if(S.page==='papers')return papersPage();
 if(S.page==='notes')return notesPage();
 if(S.page==='decisions')return decisionsPage();
 return settingsPage();
}
function overview(){
 if(!S.data.projects.length)return heading('YOUR RESEARCH, CONNECTED','Give your research a clear starting point.','Keep questions, experiments, evidence and next steps together.')+`<div class="welcome-grid"><div class="welcome-card"><span class="big-symbol">01</span><h2>Start your research</h2><p>Create a project and write down your question. Add hypotheses, data versions and experiments as you go.</p>${btn('Create your first project '+icon('arrow'),'new','data-kind="projects"','primary')}</div><div class="welcome-card sample"><span class="big-symbol">02</span><h2>Explore the demo workspace</h2><p>Three synthetic AI4S projects demonstrate seed comparisons, paper links and decisions. All metrics are marked as demo data.</p>${btn('Load demo workspace '+icon('arrow'),'demo')}</div></div><div class="welcome-foot">${icon('database')} Local experiment tracking · No account required · Export anytime</div>`;
 const hy=list('hypotheses'), ex=list('experiments'), dec=list('decisions').filter(x=>['todo','doing'].includes(x.status)), runs=list('runs');
 const ps=list('projects').filter(p=>p.status==='active');const focus=project(S.project)||[...ps].sort((a,b)=>S.data.experiments.filter(e=>e.project_id===b.id).length-S.data.experiments.filter(e=>e.project_id===a.id).length)[0]||list('projects')[0];const demo=S.data.projects.some(p=>p.description?.includes('Demo project'));
 const comparable=ex.filter(e=>metricStats(e).n>0);const anchor=comparable.find(e=>e.title.toLowerCase().includes('baseline'))||comparable[0];const chartEx=anchor?comparable.filter(e=>['project_id','dataset_id','split','metric','direction'].every(k=>e[k]===anchor[k])).sort((a,b)=>(a.id===anchor.id?-1:b.id===anchor.id?1:0)).slice(0,4):[];
 return heading('RESEARCH OVERVIEW','Give every experiment a question.',`${date(new Date(),{year:'numeric',month:'long',day:'numeric',weekday:'long'})} <span class="heading-dot">·</span> Move a promising idea forward today.`,btn(icon('plus')+' Record experiment','new','data-kind="experiments"','primary'))+
 `<div class="overview-controls">${scopeControl()}${demo?'<span class="demo-badge">DEMO <span>Contains demo data · Not real research results</span></span>':''}</div><div class="stats-grid">${[[ps.length,'Active projects','folder',`${S.data.projects.length} projects recorded`],[hy.filter(h=>h.status==='testing').length,'Hypotheses in testing','bulb',`${hy.length} traceable research questions`],[runs.filter(r=>r.status==='completed').length,'Completed runs','flask',`${ex.filter(e=>e.status==='running').length} experiments marked running`],[dec.length,'Pending decisions','arrow',`${dec.filter(d=>d.priority==='high').length} high-priority items`]].map(([n,label,ic,sub])=>`<div class="stat-card"><div class="stat-top"><span>${label}</span>${icon(ic)}</div><div class="stat-number">${n}<span>${ic==='flask'?'runs':' items'}</span></div><small>${sub}</small></div>`).join('')}</div><div class="overview-grid"><div class="overview-primary"><section class="focus-card"><div class="card-kicker"><span><i class="live-dot"></i> CURRENT FOCUS</span>${status(focus.status)}</div><div class="focus-orbit" aria-hidden="true"><i></i><i></i><i></i><b></b></div><div class="focus-content"><h2>${esc(focus.name)}</h2><p>${esc(focus.question||'Write a question worth answering for this project.')}</p><div class="focus-meta"><span>${S.data.hypotheses.filter(h=>h.project_id===focus.id).length} hypotheses</span><span>${S.data.experiments.filter(e=>e.project_id===focus.id).length} experiments</span><span>${S.data.papers.filter(p=>p.project_id===focus.id).length} paper links</span></div>${btn('Open project '+icon('arrow'),'detail',`data-kind="projects" data-id="${focus.id}"`,'focus-button')}</div></section><section class="panel comparison-panel"><div class="panel-heading"><div><div class="eyebrow">EXPERIMENT SIGNAL</div><h2>Changes behind the metrics</h2></div>${btn('Compare experiments '+icon('arrow'),'nav','data-page="experiments"','text-button')}</div>${chartEx.length?`<div class="chart-caption"><span>${esc(anchor.metric)} <small>${anchor.direction==='min'?'Lower is better':'Higher is better'} · Mean ± Sample standard deviation</small></span>${pmark(anchor.project_id)}</div>${barChart(chartEx)}<p class="panel-footnote">${icon('link')} Same data version and split · Completed runs only</p>`:'<div class="mini-empty">Record experiment results to see changes here.</div>'}</section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">RECENT NOTES</div><h2>Keep a record of your thinking</h2></div>${btn(icon('plus')+' Write note','new','data-kind="notes"','text-button')}</div>${list('notes').slice(0,2).map(n=>`<div class="note-preview">${icon('note')}<div>${openLink('notes',n)}<p>${esc(n.body?.replace(/[#>*\n]/g,' ').slice(0,90)||'No content yet')}</p><small>${pmark(n.project_id)}<span>${date(n.updated_at)}</span></small></div></div>`).join('')||'<div class="mini-empty">Record observations, interpretations and open questions.</div>'}</section></div><div class="overview-secondary"><section class="panel next-panel"><div class="panel-heading"><div><div class="eyebrow">WHAT’S NEXT</div><h2>What comes next</h2></div><span class="count-pill">${dec.length}</span></div>${dec.sort((a,b)=>({high:0,medium:1,low:2}[a.priority]-{high:0,medium:1,low:2}[b.priority])).slice(0,4).map(d=>`<div class="next-item"><button class="round-check" aria-label="Complete: ${esc(d.title)}" data-action="done" data-id="${d.id}">${icon('check')}</button><div>${openLink('decisions',d)}<p>${esc(d.rationale||'Add a reason for this step')}</p><div class="next-meta"><span class="priority ${d.priority}">${labels[d.priority]}</span>${d.due_date?`<span>${date(d.due_date+'T12:00:00')}</span>`:''}</div></div></div>`).join('')||'<div class="mini-empty">No pending decisions. Define the next step for your research.</div>'}${btn(icon('plus')+' Add next step','new','data-kind="decisions"','wide subtle')}</section><section class="panel activity-panel"><div class="panel-heading"><div><div class="eyebrow">RESEARCH TRAIL</div><h2>Recent research activity</h2></div></div>${activityHtml(listActivity().slice(0,5))}</section><div class="quiet-card"><span class="quote-mark">“</span><p>Results deserve a record,<br>including experiments without an answer.</p><small>KEEP THE QUESTION ALIVE.</small></div></div></div>`;
}
function barChart(exps,providedStats){const stats=providedStats||exps.map(metricStats);const good=stats.filter(s=>s.mean!==null);if(!good.length)return '<div class="mini-empty">No valid completed results yet.</div>';const lo=Math.min(0,...good.map(s=>s.mean-(s.sd||0))),hi=Math.max(0,...good.map(s=>s.mean+(s.sd||0)));const span=(hi-lo)||1;const min=lo<0?lo-span*.08:0,max=hi+span*.08;const scale=v=>(v-min)/(max-min)*100;const zero=scale(0);return `<div class="bar-chart">${exps.map((e,i)=>{const s=stats[i];return `<div class="bar-row"><div class="bar-label">${openLink('experiments',e)}<small>n = ${s.n} seeds</small></div><div class="bar-track">${s.mean===null?'':`<div class="bar-fill c${i}" style="position:absolute;left:${Math.min(zero,scale(s.mean))}%;width:${Math.abs(scale(s.mean)-zero)}%"></div>${s.sd?`<div class="error-bar" style="left:${scale(s.mean-s.sd)}%;width:${scale(s.mean+s.sd)-scale(s.mean-s.sd)}%"></div>`:''}`}</div><span class="bar-value">${format(s.mean)}<small>± ${format(s.sd)}</small></span></div>`;}).join('')}<div class="chart-axis"><span>${format(min,1)}</span><span>${format((min+max)/2,1)}</span><span>${format(max,1)}</span></div></div>`;}

function listActivity(){return S.data.activity.filter(a=>!S.project||a.project_id===S.project);}
function activityHtml(items){return `<div class="activity-list">${items.map(a=>`<div class="activity-item"><i></i><div><p><span>${({created:'Create',updated:'Update',deleted:'Delete',restored:'Restore'})[a.action]}${names[a.kind]||''}</span> ${esc(a.title)}</p><small>${date(a.at,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('')||'<p class="muted">Future changes will be timestamped.</p>'}</div>`;}
function projectsPage(){return heading('RESEARCH PROJECTS','Start with a good question.','Bring hypotheses, experiments and evidence around one question.',btn(icon('plus')+' New project','new','data-kind="projects"','primary'))+toolbar('projects')+tabs(['active','paused','archived'])+`<div class="project-grid">${filtered('projects').map(p=>{const es=S.data.experiments.filter(e=>e.project_id===p.id);return `<article class="project-card" style="--project:${esc(p.color)}"><div class="project-card-top"><span class="project-icon">${icon('folder')}</span>${status(p.status)}</div><h2>${openLink('projects',p)}</h2><p class="project-question">${esc(p.question||'No research question yet')}</p><div class="project-card-counts"><span><strong>${S.data.hypotheses.filter(h=>h.project_id===p.id).length}</strong> Hypothesis</span><span><strong>${es.length}</strong> Experiment</span><span><strong>${S.data.papers.filter(a=>a.project_id===p.id).length}</strong> Evidence</span></div><div class="project-progress"><i style="width:${es.length?es.filter(e=>e.status==='completed').length/es.length*100:0}%"></i></div><div class="project-card-bottom"><small>${date(p.updated_at)} Update</small>${btn('Open project '+icon('arrow'),'detail',`data-kind="projects" data-id="${p.id}"`,'text-button')}</div></article>`;}).join('')}</div>${!filtered('projects').length?empty('No projects yet','Create a dedicated space for your research direction.'):''}`;}
function hypothesesPage(){return heading('HYPOTHESES','Make the question testable.','Define predictions and criteria, then gather experimental evidence.',btn(icon('plus')+' New hypothesis','new','data-kind="hypotheses"','primary'))+toolbar('hypotheses')+tabs(['proposed','testing','supported','inconclusive','refuted'])+`<div class="hypothesis-list">${filtered('hypotheses').map((h,i)=>`<article class="hypothesis-card"><div class="hypothesis-number">H${String(i+1).padStart(2,'0')}</div><div class="hypothesis-body"><div class="card-topline">${pmark(h.project_id)}${status(h.status)}</div><h2>${openLink('hypotheses',h)}</h2><p>${esc(h.prediction||h.rationale||'Add a testable prediction for this hypothesis.')}</p><div class="criterion"><span>Decision criteria</span>${esc(h.criterion||'Not defined')}</div><div class="hypothesis-links"><span>${icon('flask')} ${S.data.experiments.filter(e=>e.hypothesis_id===h.id).length} experiments</span><span>${icon('book')} ${S.data.papers.filter(p=>p.hypothesis_id===h.id).length} evidence links</span><span>${date(h.updated_at)} Update</span></div></div>${btn(icon('arrow'),'detail',`data-kind="hypotheses" data-id="${h.id}"`,'icon-only')}</article>`).join('')}</div>${!filtered('hypotheses').length?empty('Turn intuition into a hypothesis','A testable prediction is the starting point for your next experiment.'):''}`;}
function experimentsPage(){
 const items=filtered('experiments');
 return heading('EXPERIMENT TRACKING','Trace every run.','Save configurations and results. Compare matched evaluation settings across seeds.',btn(icon('plus')+' New experiment','new','data-kind="experiments"','primary'))+toolbar('experiments',btn(icon('database')+' Data version','datasets'))+tabs(['planned','running','completed','failed'])+
 `${S.selected.size?`<div class="selection-bar"><span>Selected <b>${S.selected.size}</b> experiments · First selected is the baseline</span><div>${btn('Clear','clear-selection','','text-button')}${btn(icon('chart')+' Compare selected','compare','','primary')}</div></div>`:''}<div class="table-wrap"><table class="experiment-table"><thead><tr><th class="check-cell"><span class="sr-only">Select</span></th><th>Experiment / Project</th><th>Status</th><th>Primary metric <span class="muted">Mean ± SD</span></th><th>SEEDS</th><th>Data and split</th><th>Version</th><th></th></tr></thead><tbody>${items.map(e=>{const s=metricStats(e),ds=find('datasets',e.dataset_id);return `<tr><td class="check-cell"><input type="checkbox" aria-label="Select ${esc(e.title)}" data-select-exp="${e.id}" ${S.selected.has(e.id)?'checked':''}></td><td><div class="table-title">${openLink('experiments',e)}</div>${pmark(e.project_id)}</td><td>${status(e.status)}</td><td><div class="metric-cell">${format(s.mean)} <small>${s.n>1?'± '+format(s.sd):''}</small></div><span class="small muted">${esc(e.metric)} ${e.direction==='min'?'↓':'↑'}</span></td><td><span class="seed-count">${s.n}</span><small class="block muted">completed</small></td><td><span class="dataset-name">${esc(ds?.version||'—')}</span><small class="block muted">${esc(e.split)}</small></td><td><code>${esc(e.config_hash?.slice(0,7)||'—')}</code><small class="block muted">config</small></td><td>${btn(icon('chevron'),'detail',`data-kind="experiments" data-id="${e.id}"`,'icon-only')}</td></tr>`;}).join('')}</tbody></table>${!items.length?empty('Set up your first experiment','Choose a data version, then record the configuration and evaluation criteria.'):''}</div><p class="page-note">${icon('link')} Select 2–6 experiments for paired seed comparison. Project, data version, split and metric definitions must match.</p>${S.compare?compareHtml(S.compare):''}`;
}
function compareHtml(data){const base=data.results[0];return `<section class="panel full-comparison" id="compare-results"><div class="panel-heading"><div><div class="eyebrow">MATCHED-SEED COMPARISON</div><h2>${esc(data.metric)} <span class="muted small">${data.direction==='min'?'Lower is better':'Higher is better'}</span></h2></div>${btn(icon('download')+' Export comparison','export-comparison')}</div><p class="comparison-baseline">Baseline: <strong>${esc(base.experiment.title)}</strong> · ${esc(base.experiment.split)}</p>${barChart(data.results.map(r=>r.experiment),data.results.map(r=>r.summary))}<div class="table-wrap"><table><thead><tr><th>Experiment</th><th>Mean ± SD</th><th>Matched seeds</th><th>Paired difference</th><th>95% CI</th><th>Excluded</th></tr></thead><tbody>${data.results.map((r,i)=>`<tr><td>${esc(r.experiment.title)}${i===0?' <span class="tiny-label">Baseline</span>':''}</td><td>${format(r.summary.mean)} ± ${format(r.summary.sd)}</td><td>${r.paired.n}</td><td>${i===0?'—':format(r.paired.mean)}</td><td>${i===0?'—':r.paired.ci95?`[${r.paired.ci95.map(x=>format(x)).join(', ')}]`:'At least 2 pairs seed'}</td><td>${r.excluded}</td></tr>`).join('')}</tbody></table></div><div class="method-note">${icon('bulb')}<p>${esc(data.method)}<br>Intervals describe seed variation, not uncertainty from data sampling or different target splits. No multiple-comparison correction is applied.</p></div><details><summary>Per-seed metrics and configuration differences</summary><div class="table-wrap"><table><thead><tr><th>Seed</th>${data.results.map(r=>`<th>${esc(r.experiment.title)}</th>`).join('')}</tr></thead><tbody>${[...new Set(data.results.flatMap(r=>r.values.map(v=>v.seed)))].sort((a,b)=>a-b).map(seed=>`<tr><td>${seed}</td>${data.results.map(r=>`<td>${format(r.values.find(v=>v.seed===seed)?.value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="config-grid">${data.results.map(r=>`<div><h4>${esc(r.experiment.title)}</h4><pre>${esc(JSON.stringify(r.experiment.config,null,2))}</pre></div>`).join('')}</div></details></section>`;}
function papersPage(){return heading('EVIDENCE LIBRARY','Keep evidence behind each judgment.','Record how each paper relates to your hypothesis.',btn(icon('plus')+' Add paper','new','data-kind="papers"','primary'))+toolbar('papers')+`<div class="paper-list">${filtered('papers').map((p,i)=>`<article class="paper-card"><div class="paper-cover"><span>REF.</span><strong>${String(i+1).padStart(2,'0')}</strong>${icon('book')}</div><div class="paper-content"><div class="card-topline">${pmark(p.project_id)}${status(p.evidence_type)}</div><h2>${openLink('papers',p)}</h2><div class="paper-byline">${esc(p.authors||'Authors not recorded')}${p.year?' · '+esc(p.year):''}</div><p>${esc(p.summary||'No reading notes yet.')}</p><div class="paper-links">${p.hypothesis_id?`<span>${icon('bulb')} ${esc(find('hypotheses',p.hypothesis_id)?.title)}</span>`:''}${p.url?`<a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Read source ${icon('external')}</a>`:''}</div></div></article>`).join('')}</div>${!filtered('papers').length?empty('Build your evidence library','Add paper links, source locations and relationships to hypotheses.'):''}`;}
function notesPage(){return heading('RESEARCH NOTEBOOK','Save results and your thinking.','Link observations, interpretations and open questions to experiments.',btn(icon('plus')+' Write research note','new','data-kind="notes"','primary'))+toolbar('notes')+`<div class="notes-grid">${filtered('notes').map(n=>`<article class="note-card"><div class="card-topline">${pmark(n.project_id)}<small>${date(n.updated_at)}</small></div><h2>${openLink('notes',n)}</h2><div class="note-excerpt">${markdown(n.body||'No content yet.').slice(0,1200)}</div><div class="note-card-bottom">${icon('note')}<span>${n.experiment_id?esc(find('experiments',n.experiment_id)?.title):'Project research notes'}</span>${btn(icon('arrow'),'detail',`data-kind="notes" data-id="${n.id}"`,'icon-only')}</div></article>`).join('')}</div>${!filtered('notes').length?empty('Capture a research note','Headings, lists, quotes and code blocks with lightweight Markdown.'):''}`;}
function decisionsPage(){return heading('NEXT DECISIONS','Choose your next step with a reason.','Turn observations into actions with clear acceptance criteria.',btn(icon('plus')+' New decision','new','data-kind="decisions"','primary'))+toolbar('decisions')+`<div class="kanban">${[['todo','To do'],['doing','Active'],['done','Completed']].map(([state,label])=>{const items=filtered('decisions').filter(d=>d.status===state);return `<section class="kanban-column"><div class="kanban-heading"><h2><i class="${state}"></i>${label}</h2><span>${items.length}</span></div>${items.map(d=>`<article class="decision-card"><div class="card-topline">${pmark(d.project_id)}<span class="priority ${d.priority}">${labels[d.priority]}</span></div><h3>${openLink('decisions',d)}</h3><p>${esc(d.rationale||'Add the reason for this step.')}</p>${d.criterion?`<div class="decision-criterion">${icon('check')}<span>${esc(d.criterion)}</span></div>`:''}<div class="decision-card-bottom"><span>${d.due_date?icon('clock')+' '+date(d.due_date+'T12:00:00'):'No due date'}</span>${state!=='done'?btn(state==='todo'?'Start '+icon('arrow'):'Done '+icon('check'),'advance',`data-id="${d.id}"`,'text-button'):icon('check')}</div></article>`).join('')||'<div class="kanban-empty">No decisions yet</div>'}${state==='todo'?btn(icon('plus')+' Add next step','new','data-kind="decisions"','wide subtle'):''}</section>`;}).join('')}</div>${filtered('decisions').some(d=>d.status==='dismissed')?`<details class="dismissed"><summary>Dismissed decisions</summary>${filtered('decisions').filter(d=>d.status==='dismissed').map(d=>`<p>${openLink('decisions',d)}</p>`).join('')}</details>`:''}`;}
function settingsPage(){return heading('LOCAL BY DESIGN','Your data stays in your hands.','Experiment tracking runs locally. Export regularly to keep your records portable.')+`<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>${icon('database')} Workspace storage</h2><span class="status completed"><i></i>Connected SQLite</span></div><label class="field-label">Datasets</label><pre class="path-display">${esc(S.data.meta.data_directory)}</pre><div class="storage-counts">${kinds.map(k=>`<span><b>${S.data[k].length}</b> ${names[k]}</span>`).join('')}</div><p class="muted small">Snapshots are created at startup and before restore. The latest 20 are kept. Data is stored separately from app code.</p>${btn('Create local snapshot','backup')} ${btn('View and restore snapshots','snapshots')}</section><section class="panel"><div class="panel-heading"><h2>${icon('download')} Backup and migration</h2></div><p>JSON backups contain projects, links, configurations, metrics, curves and notes. External files are referenced by path, not copied.</p><div class="settings-actions">${btn(icon('download')+' Export full backup','export','','primary')}${btn(icon('upload')+' Restore backup','restore')}</div><p class="small muted">Restore replaces the current workspace after saving a local snapshot.</p></section><section class="panel integration-panel"><div class="panel-heading"><h2>Available integrations</h2></div><div class="integration-row"><span>${icon('git')} Local Git</span><span>Read commit, branch and uncommitted state</span><b>Available</b></div><div class="integration-row"><span>${icon('upload')} CSV Metrics</span><span>Preview, validate and batch import</span><b>Available</b></div><div class="integration-row"><span>${icon('book')} Paper links</span><span>Manual entries, evidence links and reading notes</span><b>Available</b></div><div class="integration-row muted"><span>${icon('flask')} Training runs</span><span>Manual status tracking; no SSH or GPU connection</span><b>Manual</b></div><div class="integration-row muted"><span>${icon('bulb')} Research decisions</span><span>Recorded by you; no automatic experimental conclusions</span><b>Manual</b></div></section><section class="panel"><div class="panel-heading"><h2>Start a clean workspace</h2></div><p>Demo data is for exploring features. Export first, then reset to an empty workspace.</p>${btn('Reset workspace','reset','','danger-text')}<p class="small muted">Confirmation text is required. A backup is created before clearing.</p></section></div>`;}
function markdown(text){let code=false;return String(text).split('\n').map(line=>{if(line.startsWith('```')){code=!code;return code?'<pre class="markdown-code"><code>':'</code></pre>';}if(code)return esc(line)+'\n';if(/^### /.test(line))return '<h4>'+esc(line.slice(4))+'</h4>';if(/^## /.test(line))return '<h3>'+esc(line.slice(3))+'</h3>';if(/^# /.test(line))return '<h2>'+esc(line.slice(2))+'</h2>';if(/^> /.test(line))return '<blockquote>'+esc(line.slice(2))+'</blockquote>';if(/^[-*] /.test(line))return '<p class="md-list">• '+esc(line.slice(2))+'</p>';return line?'<p>'+esc(line).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')+'</p>':'<br>';}).join('')+(code?'</code></pre>':'');}
function layer(content,{wide=false,drawer=false}={}){lastFocus=document.activeElement;$('#layers').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide-modal':''} ${drawer?'drawer':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${content}</section></div>`;document.body.classList.add('modal-open');requestAnimationFrame(()=>$('.modal input:not([type=hidden]), .modal textarea, .modal button')?.focus());}
function closeLayer(force=false){if(formDirty&&!force&&!confirm('Discard unsaved changes?'))return;$('#layers').innerHTML='';document.body.classList.remove('modal-open');formDirty=false;currentForm=null;S.detail=null;lastFocus?.focus?.();}
function modalHead(eyebrow,title){return `<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="dialog-title">${esc(title)}</h2></div>${btn(icon('close'),'close','aria-label="Close"','icon-only')}</div>`;}
function detail(kind,id){const item=find(kind,id);if(!item)return toast('Record no longer exists',true);currentForm=null;formDirty=false;S.detail={kind,id};let content='';
 const field=(label,value)=>value?`<div class="detail-field"><label>${label}</label><div>${markdown(value)}</div></div>`:'';
 const related=(title,ks,items)=>`<section class="detail-section"><div class="section-line"><h3>${title}</h3><span class="count-pill">${items.length}</span></div>${items.map(x=>`<div class="related-row">${openLink(ks,x)}${x.status?status(x.status):icon('chevron')}</div>`).join('')||'<p class="muted small">Not linked</p>'}</section>`;
 if(kind==='projects')content=field('Research question',item.question)+field('Project description',item.description)+`<div class="detail-actions">${btn(icon('bulb')+' Add hypothesis','child-new',`data-kind="hypotheses" data-project="${id}"`)}${btn(icon('flask')+' New experiment','child-new',`data-kind="experiments" data-project="${id}"`)}${btn(icon('database')+' Data version','datasets',`data-project="${id}"`)}</div>`+related('Hypotheses','hypotheses',S.data.hypotheses.filter(x=>x.project_id===id))+related('Experiment','experiments',S.data.experiments.filter(x=>x.project_id===id))+related('Next steps','decisions',S.data.decisions.filter(x=>x.project_id===id))+field('Local repository',item.repo_path);
 if(kind==='hypotheses')content=field('Rationale',item.rationale)+field('Testable prediction',item.prediction)+field('Decision criteria',item.criterion)+`<div class="detail-actions">${btn(icon('flask')+' Design linked experiment','child-new',`data-kind="experiments" data-project="${item.project_id}" data-hypothesis="${id}"`)}${btn(icon('book')+' Link paper','child-new',`data-kind="papers" data-project="${item.project_id}" data-hypothesis="${id}"`)}</div>`+related('Linked experiment','experiments',S.data.experiments.filter(x=>x.hypothesis_id===id))+related('Paper evidence','papers',S.data.papers.filter(x=>x.hypothesis_id===id))+related('Next steps','decisions',S.data.decisions.filter(x=>x.hypothesis_id===id));
 if(kind==='experiments'){
  const s=metricStats(item),ds=find('datasets',item.dataset_id),runs=S.data.runs.filter(r=>r.experiment_id===id).sort((a,b)=>a.seed-b.seed);
  content=field('Experiment purpose',item.description)+`<div class="detail-metrics"><div><small>${esc(item.metric)} ${item.direction==='min'?'↓':'↑'}</small><strong>${format(s.mean)}</strong><span>± ${format(s.sd)} SD</span></div><div><small>COMPLETED SEEDS</small><strong>${s.n}</strong><span>${runs.length} runs</span></div></div><dl class="facts"><dt>Data version</dt><dd>${esc(ds?.name)} · ${esc(ds?.version)}</dd><dt>Evaluation split</dt><dd>${esc(item.split)}</dd><dt>Hypotheses</dt><dd>${item.hypothesis_id?openLink('hypotheses',find('hypotheses',item.hypothesis_id)):'Not linked'}</dd><dt>Configuration hash</dt><dd><code>${esc(item.config_hash?.slice(0,16))}</code></dd><dt>Git commit</dt><dd><code>${esc(item.git?.commit||'Not recorded')}</code>${item.git?.dirty?'<span class="status failed">Uncommitted changes</span>':''}</dd></dl><section class="detail-section"><div class="section-line"><h3>Runs</h3><div>${btn(icon('upload')+' Import  CSV','csv',`data-id="${id}"`)}${btn(icon('plus')+' Add seed','child-new',`data-kind="runs" data-project="${item.project_id}" data-experiment="${id}"`,'primary')}</div></div><div class="table-wrap"><table><thead><tr><th>Seed</th><th>Status</th><th>${esc(item.metric)}</th><th></th></tr></thead><tbody>${runs.map(r=>`<tr><td><code>${r.seed}</code></td><td>${status(r.status)}</td><td>${format(r.metrics[item.metric])}</td><td>${btn('View','detail',`data-kind="runs" data-id="${r.id}"`,'text-button')}</td></tr>`).join('')}</tbody></table>${!runs.length?'<div class="mini-empty">No runs yet. Add one manually or import CSV.</div>':''}</div></section>${curveChart(runs)}<section class="detail-section"><h3>Configuration</h3><pre>${esc(JSON.stringify(item.config,null,2))}</pre><p class="small muted">Configuration, Git and evaluation settings are frozen after runs exist. Duplicate the experiment to try a new setup.</p></section><div class="detail-actions">${btn(icon('copy')+' Duplicate experiment','duplicate',`data-id="${id}"`)}${btn(icon('note')+' Write observation','child-new',`data-kind="notes" data-project="${item.project_id}" data-experiment="${id}"`)}${btn(icon('arrow')+' Record next step','child-new',`data-kind="decisions" data-project="${item.project_id}" data-experiment="${id}"`)}</div>`+related('Research notes','notes',S.data.notes.filter(n=>n.experiment_id===id));
 }
 if(kind==='runs')content=`<dl class="facts"><dt>Experiment</dt><dd>${openLink('experiments',find('experiments',item.experiment_id))}</dd><dt>Seed</dt><dd>${item.seed}</dd><dt>Status</dt><dd>${status(item.status)}</dd></dl><h3>Raw metrics</h3><pre>${esc(JSON.stringify(item.metrics,null,2))}</pre>${curveChart([item])}`+field('Runs',item.notes)+field('Artifact path (reference)',item.artifact_path);
 if(kind==='papers')content=`<div class="paper-byline">${esc(item.authors)} ${esc(item.year)}</div><div class="detail-actions">${status(item.evidence_type)}${item.url?`<a class="button" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Read source ${icon('external')}</a>`:''}</div>`+field('Research relevance / Source location',item.summary)+field('DOI',item.doi)+(item.hypothesis_id?related('Hypotheses','hypotheses',[find('hypotheses',item.hypothesis_id)]):'')+(item.experiment_id?related('Experiment','experiments',[find('experiments',item.experiment_id)]):'');
 if(kind==='notes')content=`<div class="markdown-body">${markdown(item.body||'No content yet.')}</div>`+(item.experiment_id?related('Linked experiment','experiments',[find('experiments',item.experiment_id)]):'')+(item.hypothesis_id?related('Linked hypothesis','hypotheses',[find('hypotheses',item.hypothesis_id)]):'');
 if(kind==='decisions')content=field('Rationale for this step',item.rationale)+field('Acceptance criteria',item.criterion)+`<dl class="facts"><dt>Priority</dt><dd>${labels[item.priority]}</dd><dt>Due date</dt><dd>${item.due_date||'Not set'}</dd></dl>`+(item.hypothesis_id?related('Hypotheses','hypotheses',[find('hypotheses',item.hypothesis_id)]):'')+(item.experiment_id?related('Linked experiment','experiments',[find('experiments',item.experiment_id)]):'');
 if(kind==='datasets')content=`<dl class="facts"><dt>Version</dt><dd>${esc(item.version)}</dd><dt>Default split</dt><dd>${esc(item.split||'Not set')}</dd><dt>Fingerprint / Hash</dt><dd><code>${esc(item.fingerprint||'Not recorded')}</code></dd><dt>File path</dt><dd>${esc(item.path||'Not recorded')}</dd></dl>`+field('Description',item.description)+related('Experiments using this version','experiments',S.data.experiments.filter(e=>e.dataset_id===id));
 layer(modalHead(names[kind].toUpperCase(),titleOf(item))+`<div class="detail-subline">${kind==='projects'?'':pmark(item.project_id)}${item.status?status(item.status):''}<small>${date(item.updated_at)} Update</small></div><div class="detail-body">${content}</div><div class="modal-footer"><button class="button danger-text" data-action="delete" data-kind="${kind}" data-id="${id}">${icon('trash')} Delete</button><span class="spacer"></span>${btn('Edit '+names[kind],'edit',`data-kind="${kind}" data-id="${id}"`,'primary')}</div>`,{drawer:true});S.detail={kind,id};
}
function curveChart(runs,chosenKey){const available=runs.filter(r=>r.history?.length);if(!available.length)return '';const keys=[...new Set(available.flatMap(r=>r.history.flatMap(p=>Object.keys(p.metrics))))];const key=chosenKey||keys.find(k=>k.startsWith('val'))||keys[0];const series=available.map(r=>({...r,points:r.history.filter(p=>Number.isFinite(p.metrics[key]))})).filter(r=>r.points.length);if(!series.length)return '';const pts=series.flatMap(r=>r.points);const minX=Math.min(...pts.map(p=>p.step)),maxX=Math.max(...pts.map(p=>p.step));const minY=Math.min(...pts.map(p=>p.metrics[key])),maxY=Math.max(...pts.map(p=>p.metrics[key]));const x=v=>48+(v-minX)/(maxX-minX||1)*502,y=v=>175-(v-minY)/(maxY-minY||1)*135;const colors=['#ce6e4d','#527c72','#7a82b3','#bb9b57','#9f6c94'];return `<section class="detail-section"><div class="section-line"><h3>Learning curves</h3><select class="curve-select" aria-label="Choose curve metric" data-curve-runs="${available.map(r=>r.id).join(',')}">${keys.map(k=>`<option ${k===key?'selected':''}>${esc(k)}</option>`).join('')}</select></div><svg class="line-chart" viewBox="0 0 580 220" role="img" aria-label="${esc(key)} by training step">${[0,.5,1].map(a=>`<line x1="48" x2="550" y1="${40+a*135}" y2="${40+a*135}" stroke="#e6e8e2"/><text x="4" y="${44+a*135}">${format(maxY-a*(maxY-minY),2)}</text>`).join('')}${series.map((r,i)=>`<polyline fill="none" stroke="${colors[i%5]}" stroke-width="2.2" points="${r.points.map(p=>`${x(p.step)},${y(p.metrics[key])}`).join(' ')}"/>${r.points.map(p=>`<circle cx="${x(p.step)}" cy="${y(p.metrics[key])}" r="3" fill="${colors[i%5]}"><title>seed ${r.seed} · step ${p.step} · ${key}: ${p.metrics[key]}</title></circle>`).join('')}`).join('')}<text x="48" y="205">${minX}</text><text x="525" y="205">${maxX} step</text></svg><div class="curve-legend">${series.map((r,i)=>`<span><i style="background:${colors[i%5]}"></i>seed ${r.seed}</span>`).join('')}</div></section>`;}
const schemas={
 projects:[['name','Project name','text',true],['question','Core research question','textarea'],['description','Project description','textarea'],['status','Project status','select',false,['active','paused','archived']],['color','Project color','colors'],['repo_path','Local Git repository path','text']],
 datasets:[['name','Dataset name','text',true],['version','Version name','text',true],['split','Default evaluation split','text'],['fingerprint','Data fingerprint / SHA-256','text'],['path','Local file path (reference)','text'],['description','Version description','textarea']],
 hypotheses:[['title','Hypothesis title','text',true],['rationale','Rationale','textarea'],['prediction','Testable prediction','textarea'],['criterion','Decision criteria','textarea'],['status','Current status','select',false,['proposed','testing','supported','inconclusive','refuted']]],
 experiments:[['title','Experiment name','text',true],['hypothesis_id','Linked hypothesis','relation'],['description','Purpose and changes','textarea'],['dataset_id','Dataset versions','relation',true],['split','Evaluation split (exact identifier)','text',true],['metric','Primary metric name (e.g. RMSE)','text',true],['direction','Metric direction','select',false,[['min','Lower is better'],['max','Higher is better']]],['status','Experiment status (manual)','select',false,['planned','running','completed','failed']],['config','Configuration · JSON','json'],['git','Git Snapshot · JSON','json'],['tags','Tags (comma-separated)','text']],
 runs:[['experiment_id','Experiment','relation',true],['seed','Random seed','number',true],['status','Run status (manual)','select',false,['planned','running','completed','failed']],['primary_value','Primary metric value','number'],['metrics','Other metrics · JSON object','json'],['history','Learning curves · JSON array (optional)','json'],['notes','Run notes / Failure reason','textarea'],['artifact_path','Artifact file path (reference)','text']],
 papers:[['title','Paper title','text',true],['authors','Authors','text'],['year','Year','text'],['url','Source URL','url'],['doi','DOI','text'],['hypothesis_id','Linked hypothesis','relation'],['experiment_id','Linked experiment','relation'],['evidence_type','Evidence relationship','select',false,['context','supports','contradicts','method']],['summary','Relevance / Summary / Source location','textarea']],
 notes:[['title','Note title','text',true],['hypothesis_id','Linked hypothesis','relation'],['experiment_id','Linked experiment','relation'],['body','Content · Supports lightweight Markdown','editor']],
 decisions:[['title','What to do next','text',true],['hypothesis_id','Linked hypothesis','relation'],['experiment_id','Linked experiment','relation'],['rationale','Rationale for this step','textarea'],['criterion','Acceptance criteria','textarea'],['status','Status','select',false,['todo','doing','done','dismissed']],['priority','Priority','select',false,['high','medium','low']],['due_date','Due date','date']]
};
const relations={project_id:'projects',hypothesis_id:'hypotheses',dataset_id:'datasets',experiment_id:'experiments'};
function fieldHtml(field,item,pid,locked=false){const [name,label,type,required,options]=field;let value=item[name]??'';const attr=`name="${name}" id="field-${name}" ${required?'required':''} ${locked?'disabled':''}`;let input='';
 if(type==='relation'||type==='select'){const opts=type==='relation'?S.data[relations[name]].filter(x=>name==='project_id'||x.project_id===pid).map(x=>[x.id,(x.name||x.title)+(x.version?' · '+x.version:'')]):options.map(o=>Array.isArray(o)?o:[o,labels[o]||o]);input=`<select ${attr}>${type==='relation'?`<option value="">${required?'Choose an option':'No link'}</option>`:''}${opts.map(([k,v])=>`<option value="${esc(k)}" ${String(value)===k?'selected':''}>${esc(v)}</option>`).join('')}</select>`;}
 else if(type==='colors')input=`<div class="color-options">${['#d76743','#497d70','#6674ad','#aa8550','#a86e91'].map(c=>`<label style="--swatch:${c}"><input type="radio" name="color" value="${c}" ${(value||'#d76743')===c?'checked':''}><span></span></label>`).join('')}</div>`;
 else if(['textarea','json','editor'].includes(type)){if(type==='json')value=JSON.stringify(value|| (name==='history'?[]:{}),null,2);input=`<textarea ${attr} class="${type}" rows="${type==='editor'?15:type==='json'?5:3}" spellcheck="${type==='json'?'false':'true'}">${esc(value)}</textarea>`;}
 else input=`<input ${attr} type="${type}" value="${esc(Array.isArray(value)?value.join(', '):value)}" ${type==='number'?'step="any"':''} ${name==='seed'?'min="0" max="4294967295" step="1"':''}>`;
 return `<div class="form-field ${['textarea','editor','json','colors'].includes(type)?'full':''}"><label for="field-${name}">${label}${required?' <em>*</em>':''}${locked?' <small>Frozen</small>':''}</label>${input}${name==='git'&&!locked?btn(icon('git')+' Capture repository snapshot','capture-git','type="button"','small-button'):''}${name==='history'?'<small class="field-hint">Format: [{"step": 1, "metrics": {"train_loss": 0.5, "val_RMSE": 2.6}}]</small>':''}${name==='repo_path'?'<small class="field-hint">For example /Users/you/research/project. Read only when requested; the repository is not modified.</small>':''}</div>`;
}
let afterDataset=null;
function newForm(kind,id=null,defaults={}){
 if(kind!=='projects'&&!S.data.projects.length){toast('Create a project first.');kind='projects';id=null;}
 const source=id?find(kind,id):null;let item={...defaults,...(source||{})};let pid=item.project_id||S.project||S.data.projects.find(p=>p.status==='active')?.id||S.data.projects[0]?.id;
 if(kind==='experiments'&&!id&&!S.data.datasets.some(d=>d.project_id===pid)){afterDataset={...defaults,project_id:pid};toast('Register a data version for this project first.');return newForm('datasets',null,{project_id:pid});}
 if(kind!=='projects')item.project_id=pid;
 if(kind==='experiments'&&!id){const ds=S.data.datasets.find(d=>d.project_id===pid);item={dataset_id:ds?.id,split:ds?.split||'',metric:'RMSE',direction:'min',config:{},git:{},...item};}
 if(kind==='runs'){const exp=find('experiments',item.experiment_id)||S.data.experiments.find(e=>e.project_id===pid);item.experiment_id=exp?.id;item.primary_value=item.metrics?.[exp?.metric]??'';item.metrics={...(item.metrics||{})};delete item.metrics[exp?.metric];if(!id)item.status='completed';}
 if(kind==='decisions'&&!item.priority)item.priority='medium';
 const locked=kind==='experiments'&&id&&S.data.runs.some(r=>r.experiment_id===id);const frozen=new Set(['dataset_id','split','metric','direction','config','git']);
 const fields=(kind==='projects'?[]:[['project_id','Project','relation',true]]).concat(schemas[kind]);
 layer(modalHead(id?'EDIT RECORD':'NEW RECORD',`${id?'Edit ':'New '}${names[kind]}`)+`<form id="record-form" data-kind="${kind}" data-id="${id||''}"><div class="form-body">${locked?'<div class="notice">Runs already exist, so configuration and evaluation settings are frozen. Use Duplicate experiment”.</div>':''}<div id="form-error" class="form-error" role="alert" hidden></div><div class="form-grid">${fields.map(f=>fieldHtml(f,item,pid,(locked&&frozen.has(f[0]))||(!!id&&f[0]==='project_id'))).join('')}</div></div><div class="modal-footer"><span class="small muted">${id?'Update local record':'Save to local workspace'}</span><span class="spacer"></span>${btn('Cancel','close','type="button"')}<button class="button primary" type="submit">${icon('check')} Save${names[kind]}</button></div></form>`,{wide:kind==='notes'});
 currentForm={kind,id,item,source};formDirty=false;
}
async function saveForm(form){const ctx=currentForm;if(!ctx)return;const save=$('button[type=submit]',form);save.disabled=true;const error=$('#form-error');error.hidden=true;
 try{const raw=Object.fromEntries(new FormData(form).entries());const data={...(ctx.source||{}),...raw};for(const key of ['id','created_at','updated_at','config_hash'])delete data[key];
 if(ctx.kind==='experiments'){for(const key of ['config','git'])data[key]=raw[key]!==undefined?JSON.parse(raw[key]||'{}'):data[key];data.tags=String(raw.tags||'').split(/[,, ]/).map(t=>t.trim()).filter(Boolean);}
 if(ctx.kind==='runs'){if(!/^\d+$/.test(raw.seed))throw new Error('Seed must be a nonnegative integer.');data.seed=Number(raw.seed);data.metrics=JSON.parse(raw.metrics||'{}');data.history=JSON.parse(raw.history||'[]');const exp=find('experiments',raw.experiment_id);if(raw.primary_value!=='')data.metrics[exp.metric]=Number(raw.primary_value);delete data.primary_value;}
 const saved=await api(ctx.kind+(ctx.id?'/'+ctx.id:''),data,ctx.id?'PUT':'POST');formDirty=false;closeLayer(true);await refresh();toast('Saved'+names[ctx.kind]);if(ctx.kind==='datasets'&&afterDataset){const next={...afterDataset,dataset_id:saved.id,split:saved.split||''};afterDataset=null;newForm('experiments',null,next);}else detail(ctx.kind,saved.id);
 }catch(e){error.textContent=e instanceof SyntaxError?'JSON format is invalid. Check quotes, commas and brackets.':e.message;error.hidden=false;error.scrollIntoView({block:'nearest'});}finally{save.disabled=false;}}
function datasetsPanel(pid){if(pid){S.project=pid;localStorage.setItem('ros-project',pid);}formDirty=false;currentForm=null;layer(modalHead('DATA VERSIONS','Datasets and versions')+`<div class="dialog-content"><p class="muted">Each version has a separate identity. Version, split and fingerprint are frozen once used by an experiment.</p>${list('datasets').map(d=>`<div class="dataset-row"><div>${openLink('datasets',d)}<p>${pmark(d.project_id)} <code>${esc(d.version)}</code> · ${esc(d.split||'No default split')}</p></div>${btn('View','detail',`data-kind="datasets" data-id="${d.id}"`,'text-button')}</div>`).join('')||'<div class="mini-empty">No data versions in this scope.</div>'}</div><div class="modal-footer"><span class="spacer"></span>${btn(icon('plus')+' New data version','new','data-kind="datasets"','primary')}</div>`);}
function csvDialog(id){const exp=find('experiments',id);csvPreview=null;currentForm=null;formDirty=false;layer(modalHead('IMPORT RUNS','Import CSV runs')+`<div class="dialog-content"><p><strong>${esc(exp.title)}</strong> · Primary metric ${esc(exp.metric)}</p><p class="muted small">A seed column is required. status and notes are optional; other columns must be numeric metrics. Status defaults to completed. Failed runs may omit metrics. Duplicate seeds are not overwritten.</p><input id="csv-file" type="file" accept=".csv,text/csv" aria-label="Choose CSV file"><textarea id="csv-content" class="csv-input" placeholder="seed,status,${esc(exp.metric)}\n11,completed,2.61\n22,completed,2.49" rows="8" aria-label="CSV Content"></textarea><div id="csv-result"></div></div><div class="modal-footer">${btn('Download template','csv-template',`data-id="${id}"`,'text-button')}<span class="spacer"></span>${btn('Validate and preview','csv-preview',`data-id="${id}"`,'primary')}<button class="button primary" data-action="csv-commit" data-id="${id}" id="csv-commit" disabled>Confirm import</button></div>`,{wide:true});}
async function previewCSV(id){csvPreview=null;$('#csv-commit').disabled=true;const content=$('#csv-content').value;const r=await api('import-csv',{experiment_id:id,content});csvPreview={id,content,result:r};$('#csv-result').innerHTML=`<div class="notice ${r.errors.length?'warning':''}">${r.count} rows passed,${r.errors.length} rows with errors.${r.errors.length?'Fix errors before importing.':'All records will be submitted together.'}</div>${r.errors.map(e=>`<p class="error-text">Page  ${e.line} : ${esc(e.message)}</p>`).join('')}<div class="table-wrap"><table><thead><tr><th>Seed</th><th>Status</th><th>Metrics</th></tr></thead><tbody>${r.rows.map(row=>`<tr><td>${row.seed}</td><td>${status(row.status)}</td><td><code>${esc(JSON.stringify(row.metrics))}</code></td></tr>`).join('')}</tbody></table></div>${r.count>20?'<p class="small muted">Showing the first 20 rows.</p>':''}`;$('#csv-commit').disabled=!!r.errors.length||!r.count;}
function download(content,name,type='application/json'){if(window.webkit?.messageHandlers?.exportFile){window.webkit.messageHandlers.exportFile.postMessage({content,name,type});return;}const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function searchDialog(){currentForm=null;layer(modalHead('QUICK FIND','Search entire workspace')+`<div class="search-dialog"><div class="search-large">${icon('search')}<input id="global-search" placeholder="Projects, hypotheses, experiments, papers, notes…" aria-label="Global search" autocomplete="off"></div><div id="search-results"><div class="mini-empty">Search all projects and research content.</div></div><div class="search-hint"><kbd>Esc</kbd> Close · Search titles, content, configurations and metrics</div></div>`);$('#global-search').focus();}
function searchResults(q){const found=q.trim()?kinds.flatMap(k=>S.data[k].filter(x=>JSON.stringify(x).toLowerCase().includes(q.toLowerCase())).map(x=>({kind:k,item:x}))).slice(0,40):[];$('#search-results').innerHTML=found.map(({kind,item})=>`<button class="search-result" data-action="detail" data-kind="${kind}" data-id="${item.id}"><span class="search-kind">${names[kind]}</span><div><strong>${esc(titleOf(item))}</strong><small>${kind==='projects'?'Project':esc(project(item.project_id)?.name)}</small></div>${icon('arrow')}</button>`).join('')||`<div class="mini-empty">${q?'No matching records.':'Enter a query to search your research content.'}</div>`;}
function restoreDialog(reset=false){currentForm=null;formDirty=false;layer(modalHead('WORKSPACE RESTORE',reset?'Reset workspace':'Restore workspace from backup')+`<div class="dialog-content"><div class="notice warning">${reset?'All current workspace records will be removed.':'The backup will replace all current records.'}A local snapshot will be saved first.</div>${reset?'':'<label class="field-label" for="restore-file">Research OS JSON Backup</label><input id="restore-file" type="file" accept=".json,application/json">'}<label class="field-label" for="restore-confirm">Type ${reset?'RESET':'RESTORE'} to confirm</label><input id="restore-confirm" autocomplete="off"><div id="restore-error" class="form-error" hidden></div></div><div class="modal-footer">${btn('Cancel','close')}<span class="spacer"></span>${btn(reset?'Confirm reset':'Confirm restore',reset?'reset-commit':'restore-commit','','danger')}</div>`);}
async function restoreCommit(reset){const confirmWord=$('#restore-confirm').value;if(confirmWord!==(reset?'RESET':'RESTORE'))throw new Error('Enter the confirmation text first.');let document;if(reset){document={format:'researchos',version:1,data:Object.fromEntries(kinds.map(k=>[k,[]]))};}else{const f=$('#restore-file').files[0];if(!f)throw new Error('Choose a backup file.');if(f.size>20*1024*1024)throw new Error('Backup file must not exceed 20 MB.');document=JSON.parse(await f.text());}await api('restore',{document,confirmation:'RESTORE'});closeLayer(true);S.project='';S.selected.clear();S.compare=null;S.page='overview';location.hash='overview';localStorage.removeItem('ros-project');await refresh();toast(reset?'Created an empty workspace':'Workspace restored. Previous data is saved in a local snapshot.');}
async function act(button){const a=button.dataset.action,id=button.dataset.id,kind=button.dataset.kind;
 switch(a){
 case 'nav':if(formDirty&&!confirm('Discard unsaved changes?'))return;closeLayer(true);S.page=button.dataset.page;S.filter='';S.query='';S.compare=null;draw();location.hash=S.page;break;
 case 'refresh':await refresh();toast('Local data refreshed');break;
 case 'mobile':$('.sidebar').classList.toggle('mobile-open');break;
 case 'scope':S.project=id;localStorage.setItem('ros-project',id);S.page='overview';S.filter='';S.query='';S.compare=null;S.selected.clear();draw();break;
 case 'filter':S.filter=button.dataset.value;draw();break;
 case 'new':if(formDirty&&!confirm('Discard unsaved changes?'))return;afterDataset=null;newForm(kind);break;
 case 'child-new':newForm(kind,null,{project_id:button.dataset.project,...(button.dataset.hypothesis?{hypothesis_id:button.dataset.hypothesis}:{}),...(button.dataset.experiment?{experiment_id:button.dataset.experiment}:{})});break;
 case 'detail':detail(kind,id);break;
 case 'edit':newForm(kind,id);break;
 case 'close':closeLayer();break;
 case 'delete':{const item=find(kind,id);if(!confirm(`Delete “${titleOf(item)}”? A snapshot will be saved first. Restore it in Settings. Referenced records cannot be deleted.`))return;await api(kind+'/'+id,{revision:item.revision},'DELETE');closeLayer(true);S.selected.delete(id);S.compare=null;await refresh();toast('Record deleted');break;}
 case 'done':case 'advance':{const item=find('decisions',id);await api('decisions/'+id,{...item,status:a==='done'?'done':item.status==='todo'?'doing':'done'},'PUT');await refresh();toast('Decision updated');break;}
 case 'datasets':datasetsPanel(button.dataset.project);break;
 case 'duplicate':{const e={...find('experiments',id)};['id','revision','created_at','updated_at','config_hash'].forEach(k=>delete e[k]);e.title+=' · copy';e.status='planned';newForm('experiments',null,e);break;}
 case 'clear-selection':S.selected.clear();S.compare=null;draw();break;
 case 'compare':S.compare=await api('compare',{ids:[...S.selected]});draw();$('#compare-results').scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'export-comparison':download(JSON.stringify(S.compare,null,2),'researchos-comparison.json');toast('Comparison export started');break;
 case 'capture-git':{const pid=$('#field-project_id').value;const p=project(pid);if(!p.repo_path)throw new Error('Set the local Git repository path in project settings first.');const git=await api('git',{path:p.repo_path});$('#field-git').value=JSON.stringify(git,null,2);formDirty=true;toast('Git snapshot read. Save the experiment to keep it.');break;}
 case 'csv':csvDialog(id);break;
 case 'csv-preview':await previewCSV(id);break;
 case 'csv-commit':if(!csvPreview||csvPreview.content!==$('#csv-content').value)throw new Error('Content changed. Validate and preview again.');await api('import-csv',{experiment_id:id,content:csvPreview.content,commit:true});closeLayer(true);await refresh();detail('experiments',id);toast(`Imported ${csvPreview.result.count} runs`);break;
 case 'csv-template':{const e=find('experiments',id);download(`seed,status,${e.metric},notes\n11,completed,,Enter measured metrics\n22,completed,,Enter measured metrics\n`,'runs-template.csv','text/csv;charset=utf-8');break;}
 case 'search':searchDialog();break;
 case 'export':download(JSON.stringify(await api('export'),null,2),`researchos-backup-${new Date().toISOString().slice(0,10)}.json`);toast('Full backup export started');break;
 case 'backup':{const r=await api('backup',{});toast('Local snapshot saved: '+r.path);break;}
 case 'snapshots':await snapshotDialog();break;
 case 'recover-snapshot':if(!confirm('Replace the workspace with this snapshot? Current data will be backed up first.'))return;await api('recover-snapshot',{name:button.dataset.name,confirmation:'RESTORE'});closeLayer(true);await refresh();toast('Workspace restored from local snapshot');break;
 case 'restore':restoreDialog();break;
 case 'reset':restoreDialog(true);break;
 case 'restore-commit':await restoreCommit(false);break;
 case 'reset-commit':await restoreCommit(true);break;
 case 'demo':await api('demo',{});await refresh();toast('Demo workspace loaded. All metrics are synthetic.');break;
 }
}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;e.preventDefault();button.disabled=true;try{await act(button);}catch(error){toast(error.message,true);}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('submit',e=>{if(e.target.id==='record-form'){e.preventDefault();saveForm(e.target);}});
document.addEventListener('input',e=>{if(e.target.closest('#record-form'))formDirty=true;if(e.target.id==='global-search')searchResults(e.target.value);if(e.target.id==='csv-content'){csvPreview=null;$('#csv-commit').disabled=true;}if(e.target.id==='list-query'){const pos=e.target.selectionStart;S.query=e.target.value;draw();const field=$('#list-query');field.focus();field.setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{try{if(e.target.dataset.curveRuns){const ids=e.target.dataset.curveRuns.split(',');e.target.closest('.detail-section').outerHTML=curveChart(S.data.runs.filter(r=>ids.includes(r.id)),e.target.value);}if(e.target.id==='project-scope'){S.project=e.target.value;localStorage.setItem('ros-project',S.project);S.selected.clear();S.compare=null;draw();}
 if(e.target.dataset.selectExp){if(e.target.checked){S.selected.add(e.target.dataset.selectExp);}else S.selected.delete(e.target.dataset.selectExp);S.compare=null;draw();}
 if(e.target.id==='csv-file'&&e.target.files[0]){if(e.target.files[0].size>4_000_000)throw new Error('CSV Maximum 4 MB.');$('#csv-content').value=await e.target.files[0].text();csvPreview=null;$('#csv-commit').disabled=true;}
 if(e.target.id==='field-project_id'&&currentForm){const pid=e.target.value;for(const name of ['hypothesis_id','experiment_id','dataset_id']){const el=$('#field-'+name);if(el){el.innerHTML='<option value="">Choose an option</option>'+S.data[relations[name]].filter(x=>x.project_id===pid).map(x=>`<option value="${x.id}">${esc(titleOf(x))}${x.version?' · '+esc(x.version):''}</option>`).join('');}}}
 if(e.target.id==='field-dataset_id'){const ds=find('datasets',e.target.value);if(ds&&$('#field-split')&&!$('#field-split').disabled)$('#field-split').value=ds.split||'';}
 }catch(error){toast(error.message,true);}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!formDirty)searchDialog();}if(e.key==='Escape')closeLayer();if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&$('#record-form')){$('#record-form').requestSubmit();}if(e.key==='Tab'&&$('.modal')){const focusables=$$('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href]', $('.modal')).filter(x=>x.offsetParent!==null);const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('beforeunload',e=>{if(formDirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if([...navs.map(n=>n[0]),'settings'].includes(page)&&page!==S.page){S.page=page;S.query='';S.filter='';draw();}});
(async()=>{try{const p=location.hash.slice(1);if([...navs.map(n=>n[0]),'settings'].includes(p))S.page=p;await refresh();}catch(e){$('#app').innerHTML=`<div class="boot"><span class="brand-mark">r<span>•</span></span><h2>Workspace unavailable</h2><p>${esc(e.message)}</p><a class="button primary" href="/">Reopen</a></div>`;}})();

async function snapshotDialog(){const result=await api('snapshots');currentForm=null;formDirty=false;layer(modalHead('LOCAL SNAPSHOTS','Local recovery points')+`<div class="dialog-content"><p class="muted small">The latest 20 snapshots are kept. Restore replaces the workspace. External files are not included.</p>${result.snapshots.map(x=>`<div class="dataset-row"><div><strong class="small">${esc(x.name)}</strong><p>${date(x.modified,{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})} · ${(x.bytes/1024).toFixed(0)} KB</p></div>${btn('Restore','recover-snapshot',`data-name="${esc(x.name)}"`,'text-button')}</div>`).join('')||'<div class="mini-empty">No snapshots yet.</div>'}</div><div class="modal-footer"><span class="spacer"></span>${btn('Close','close')}</div>`,{wide:true});}
